package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type EmpRec struct { // 01 EMP-REC, 17 bytes
	ErId    string          // PIC X(5) @0 len=5
	ErDept  string          // PIC X(3) @5 len=3
	ErHours decimal.Decimal // PIC 9(3)V9 @8 len=4
	ErRate  decimal.Decimal // PIC 9(3)V99 @12 len=5
}

var WsEofFlag string = "N"
var WsFirstFlag string = "Y"
var WsPrevDept string = "   "
var WsRegHours decimal.Decimal = decimal.NewFromInt(0)
var WsOtHours decimal.Decimal = decimal.NewFromInt(0)
var WsGross decimal.Decimal = decimal.NewFromInt(0)
var WsDeptTotal decimal.Decimal = decimal.NewFromInt(0)
var WsDeptCount int64 = 0
var WsGrandTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrandCount int64 = 0
var WsHoursEd string
var WsRateEd string
var WsGrossEd string
var WsDeptEd string
var WsGrandEd string

var EmpRecData EmpRec
var empLines []string
var empIdx int
var empFileHandle *os.File

func main() {
	MainPara()
}

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func isFirstRecord() bool {
	return WsFirstFlag == "Y"
}

func pow10Int64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func fitTruncated(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	t := d.Truncate(scale)
	scaled := t.Shift(scale)
	iv := scaled.IntPart()
	mod := pow10Int64(intDigits + int(scale))
	mv := iv % mod
	return decimal.New(mv, -scale)
}

func fitRounded(d decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	r := d.Round(scale)
	scaled := r.Shift(scale)
	iv := scaled.IntPart()
	mod := pow10Int64(intDigits + int(scale))
	mv := iv % mod
	return decimal.New(mv, -scale)
}

func parseImplied(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	intPlaces := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == 'z' || ch == '9' {
			intPlaces++
		}
	}
	fracLen := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == 'z' || ch == '9' {
			fracLen++
		}
	}
	tv := v.Truncate(int32(fracLen))
	if tv.IsNegative() {
		tv = tv.Neg()
	}
	scaled := tv.Shift(int32(fracLen))
	sInt := scaled.IntPart()
	var powFrac int64 = 1
	for i := 0; i < fracLen; i++ {
		powFrac *= 10
	}
	var intPart, fracPart int64
	if powFrac != 0 {
		intPart = sInt / powFrac
		fracPart = sInt % powFrac
		if fracPart < 0 {
			fracPart = -fracPart
		}
		if intPart < 0 {
			intPart = -intPart
		}
	}
	var powInt int64 = 1
	for i := 0; i < intPlaces; i++ {
		powInt *= 10
	}
	if powInt != 0 {
		intPart = intPart % powInt
	}
	intStr := fmt.Sprintf("%0*d", intPlaces, intPart)
	fracStr := ""
	if fracLen > 0 {
		fracStr = fmt.Sprintf("%0*d", fracLen, fracPart)
	}
	var out strings.Builder
	digitIdx := 0
	stillSuppressed := true
	for _, ch := range intPic {
		if ch == 'Z' || ch == 'z' {
			d := intStr[digitIdx]
			digitIdx++
			if stillSuppressed && d == '0' {
				out.WriteByte(' ')
			} else {
				out.WriteByte(d)
				stillSuppressed = false
			}
		} else if ch == '9' {
			d := intStr[digitIdx]
			digitIdx++
			out.WriteByte(d)
			stillSuppressed = false
		} else if ch == ',' {
			if stillSuppressed {
				out.WriteByte(' ')
			} else {
				out.WriteByte(',')
			}
		} else {
			out.WriteByte(byte(ch))
		}
	}
	if dotIdx >= 0 {
		out.WriteByte('.')
		fi := 0
		for _, ch := range fracPic {
			if ch == 'Z' || ch == 'z' || ch == '9' {
				out.WriteByte(fracStr[fi])
				fi++
			} else {
				out.WriteByte(byte(ch))
			}
		}
	}
	return out.String()
}

func formatCount(v int64, width int) string {
	mod := pow10Int64(width)
	vm := v % mod
	if vm < 0 {
		vm = -vm
	}
	return fmt.Sprintf("%0*d", width, vm)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			empLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		scanner := bufio.NewScanner(f)
		empLines = nil
		for scanner.Scan() {
			empLines = append(empLines, scanner.Text())
		}
		if serr := scanner.Err(); serr != nil {
			fmt.Fprintln(os.Stderr, serr)
			f.Close()
			os.Exit(1)
		}
		empFileHandle = f
	}
	empIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		DeptBreakPara()
	}
	if empFileHandle != nil {
		empFileHandle.Close()
		empFileHandle = nil
	}
	GrandPara()
}

func ReadPara() {
	if empIdx >= len(empLines) {
		WsEofFlag = "Y"
		return
	}
	line := empLines[empIdx]
	empIdx++
	if len(line) < 17 {
		line += strings.Repeat(" ", 17-len(line))
	} else if len(line) > 17 {
		line = line[:17]
	}
	EmpRecData.ErId = line[0:5]
	EmpRecData.ErDept = line[5:8]
	EmpRecData.ErHours = parseImplied(line[8:12], 1)
	EmpRecData.ErRate = parseImplied(line[12:17], 2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevDept = EmpRecData.ErDept
		WsFirstFlag = "N"
	} else {
		if EmpRecData.ErDept != WsPrevDept {
			DeptBreakPara()
			WsPrevDept = EmpRecData.ErDept
		}
	}
	PayPara()
	ReadPara()
}

func PayPara() {
	forty := decimal.NewFromInt(40)
	if EmpRecData.ErHours.GreaterThan(forty) {
		WsRegHours = fitTruncated(decimal.NewFromInt(40), 3, 1)
		WsOtHours = fitTruncated(EmpRecData.ErHours.Sub(forty), 3, 1)
	} else {
		WsRegHours = fitTruncated(EmpRecData.ErHours, 3, 1)
		WsOtHours = fitTruncated(decimal.NewFromInt(0), 3, 1)
	}
	rate := EmpRecData.ErRate
	onePointFive := decimal.New(15, -1)
	part1 := WsRegHours.Mul(rate)
	part2 := WsOtHours.Mul(rate).Mul(onePointFive)
	grossRaw := part1.Add(part2)
	WsGross = fitRounded(grossRaw, 7, 2)
	WsDeptTotal = fitTruncated(WsDeptTotal.Add(WsGross), 9, 2)
	WsDeptCount = (WsDeptCount + 1) % 1000
	WsGrandTotal = fitTruncated(WsGrandTotal.Add(WsGross), 11, 2)
	WsGrandCount = (WsGrandCount + 1) % 100000
	WsHoursEd = formatEdited(EmpRecData.ErHours, "ZZ9.9")
	WsRateEd = formatEdited(EmpRecData.ErRate, "ZZ9.99")
	WsGrossEd = formatEdited(WsGross, "Z,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", EmpRecData.ErId, EmpRecData.ErDept, WsHoursEd, WsRateEd, WsGrossEd)
}

func DeptBreakPara() {
	WsDeptEd = formatEdited(WsDeptTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsDeptCount, 3)
	fmt.Printf("  DEPT %s EMPLOYEES: %s TOTAL: %s\n", WsPrevDept, countStr, WsDeptEd)
	WsDeptTotal = decimal.NewFromInt(0)
	WsDeptCount = 0
}

func GrandPara() {
	WsGrandEd = formatEdited(WsGrandTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := formatCount(WsGrandCount, 5)
	fmt.Printf("GRAND TOTAL (%s): %s\n", countStr, WsGrandEd)
}
